<?php
/** اقلام مزد و کسور و تعرفه‌های سالانه، نسخه‌دار با تاریخ اثر (PAY-04)؛ کد کارگاه بیمه. */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Ctx,Db,Jalali,Money,Request,Settings};
use Agah\Erp\Modules\Payroll\PayItemService;
if(!defined('ABSPATH'))exit;
$edit=Ctx::can('payroll.edit');$unit=Ctx::unit();$u=' ('.Money::unitLabel($unit).')';
$years=Db::rows('SELECT id,title,start_date,end_date FROM '.Db::t('fiscal_years').' WHERE company_id=%d ORDER BY start_date DESC',$cid);$year=Request::int('get','year_id')?:(int)($years[0]['id']??0);
$accounts=[0=>'انتخاب حساب'];foreach(Db::rows('SELECT id,code,name FROM '.Db::t('accounts')." WHERE company_id=%d AND level=3 AND is_active=1 AND stmt_class IN ('opex','liability_current') ORDER BY code",$cid) as $a)$accounts[$a['id']]=$a['code'].' — '.$a['name'];
?>
<section class="erp-card"><h2>اقلام و تعرفه‌های حقوق</h2><p class="muted">هر تغییر، نسخهٔ تازه با «از تاریخ» می‌سازد؛ ماه‌های پیش از آن با نسخهٔ قبلی محاسبه می‌شوند و لیست‌های قطعی دست نمی‌خورند. مقادیر پیش‌فرض صرفاً نمونه‌اند؛ مشمول مالیات و بیمه بودن و سقف‌ها را طبق مقررات روز تعیین کنید.</p>
<h3>اقلام مزد و کسور</h3>
<table class="erp-table"><thead><tr><th>کد</th><th>نام</th><th>نوع</th><th>روش</th><th>مشمول مالیات</th><th>مشمول بیمه</th><th>سقف</th><th>از تاریخ</th><th>نسخه</th><th></th></tr></thead><tbody>
<?php foreach(PayItemService::items($cid) as $it): ?><tr><td dir="ltr"><?php echo esc_html($it['code']); ?></td><td><?php echo esc_html($it['name'].((int)$it['is_active']?'':' (غیرفعال)')); ?></td><td><?php echo esc_html(PayItemService::KINDS[$it['kind']]); ?></td><td><?php echo esc_html(PayItemService::CALCS[$it['calc']]); ?></td><td><?php echo $it['taxable']?'بله':'خیر'; ?></td><td><?php echo $it['insurable']?'بله':'خیر'; ?></td><td><?php echo esc_html((int)$it['ceiling']?Money::fmt((int)$it['ceiling'],$unit):'—'); ?></td><td><?php echo esc_html(Jalali::format($it['effective_from'])); ?></td><td><?php echo esc_html(Money::toFa((string)$it['version'])); ?></td><td><?php if($edit): ?><form method="post" class="erp-inline-form"><?php self::form('module_payitem_delete',$cid,'payroll_setup',$it['id']); ?><button type="submit" class="btn btn-outline btn-sm" data-confirm="این نسخه حذف شود؟ (فقط اگر در لیست حقوق به کار نرفته باشد)">حذف</button></form><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table>
<?php if($edit): ?>
<form method="post" class="erp-inline-form"><?php self::form('module_payitem_seed',$cid,'payroll_setup'); ?><input type="hidden" name="effective_from" value="<?php echo esc_attr(Jalali::format($years[0]['start_date']??Jalali::today(),false)); ?>"><button type="submit" class="btn btn-outline">افزودن اقلام پیشنهادی (اولاد، مسکن، بن، رفاهی، انگیزشی، جذب، شغل، فوق‌العاده، سایر، قسط وام)</button></form>
<form method="post" class="erp-form"><h4>نسخهٔ تازه یا قلم تازه</h4><?php self::form('module_payitem_version',$cid,'payroll_setup'); self::input('code','کد (لاتین بزرگ)','','text','required maxlength="30" dir="ltr"'); self::input('title','نام','','text','required maxlength="190"'); self::select('kind','نوع',PayItemService::KINDS,'earning'); self::select('calc','روش محاسبه',PayItemService::CALCS,'prorated'); self::input('ceiling','سقف ماهانه (صفر = بدون سقف)'.$u,'0','text'); self::input('effective_from','از تاریخ','','text','required data-jalali maxlength="10"'); ?>
<label><input type="checkbox" name="taxable" value="1" checked> مشمول مالیات</label><label><input type="checkbox" name="insurable" value="1" checked> مشمول بیمه</label><label><input type="checkbox" name="is_active" value="1" checked> فعال (برای توقف از این تاریخ، تیک را بردارید)</label>
<button type="submit" class="btn btn-primary">ذخیرهٔ نسخه</button></form>
<?php endif; ?>
<h3>تعرفه‌ها و سقف‌های سال</h3>
<form method="get" action="<?php echo esc_url(agah_erp_url()); ?>" class="erp-filter"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="payroll_setup"><label>سال مالی<select name="year_id"><?php foreach($years as $y): ?><option value="<?php echo (int)$y['id']; ?>" <?php selected($year,(int)$y['id']); ?>><?php echo esc_html($y['title']); ?></option><?php endforeach; ?></select></label><button type="submit" class="btn btn-outline">نمایش</button></form>
<p class="muted">ماه‌هایی که پیش از اولین نسخه‌اند، از «پارامترهای سالانه حقوق» (نسخهٔ ۰) محاسبه می‌شوند. حساب‌ها اگر خالی بمانند از پارامتر سالانه برداشته می‌شوند.</p>
<table class="erp-table"><thead><tr><th>نسخه</th><th>از تاریخ</th><th>بیمهٔ کارمند / کارفرما</th><th>سقف بیمه</th><th>معافیت مالیات</th><th>پله‌ها</th></tr></thead><tbody><?php foreach(PayItemService::tariffs($cid,$year) as $t): $pp=json_decode($t['params_json'],true); ?><tr><td><?php echo esc_html(Money::toFa((string)$t['version'])); ?></td><td><?php echo esc_html(Jalali::format($t['effective_from'])); ?></td><td><?php echo esc_html(Money::toFa(($pp['employee_bp']/100).'٪ / '.($pp['employer_bp']/100).'٪')); ?></td><td><?php echo esc_html((int)$pp['insurance_ceiling']?Money::fmt((int)$pp['insurance_ceiling'],$unit):'—'); ?></td><td><?php echo esc_html(Money::fmt((int)$pp['tax_exemption'],$unit)); ?></td><td><?php echo esc_html(Money::toFa((string)count($pp['brackets']))); ?></td></tr><?php endforeach; ?></tbody></table>
<?php if($edit&&$year): ?><form method="post" class="erp-form"><h4>نسخهٔ تازهٔ تعرفه</h4><?php self::form('module_tariff_save',$cid,'payroll_setup'); ?><input type="hidden" name="year_id" value="<?php echo (int)$year; ?>">
<?php self::input('effective_from','از تاریخ','','text','required data-jalali maxlength="10"'); foreach(['employee_bp'=>'سهم بیمهٔ کارمند (٪)','employer_bp'=>'سهم بیمهٔ کارفرما (٪)','overtime_percent'=>'ضریب اضافه‌کار (٪، مثلاً 140)'] as $k=>$l)self::input($k,$l,'','text','required inputmode="decimal"'); self::input('monthly_minutes','دقیقهٔ کار ماهانهٔ مبنا','13200','number','required min="1"'); foreach(['insurance_ceiling'=>'سقف دستمزد مشمول بیمه (۳۰ روز، صفر = بدون سقف)','tax_exemption'=>'معافیت ماهانهٔ مالیات'] as $k=>$l)self::input($k,$l.$u,'0','text','required'); self::input('insurance_tax_numerator','کسر بیمه از مالیات: صورت','2','number','min="0" max="100"'); self::input('insurance_tax_denominator','مخرج','7','number','min="1" max="100"');
for($i=0;$i<5;$i++){self::input('upper_'.$i,'سقف پلهٔ '.($i+1).$u.' (خالی = آخرین پله)','','text');self::input('rate_'.$i,'نرخ پلهٔ '.($i+1).' (٪)','','text','inputmode="decimal"');}
foreach(['expense_account_id'=>'حساب هزینهٔ حقوق','salary_account_id'=>'حساب حقوق پرداختنی','insurance_account_id'=>'حساب بیمهٔ پرداختنی','tax_account_id'=>'حساب مالیات پرداختنی','deduction_account_id'=>'حساب سایر کسورات'] as $k=>$l)self::select($k,$l.' (اختیاری)',$accounts,0); ?>
<button type="submit" class="btn btn-primary">ذخیرهٔ نسخهٔ تعرفه</button></form><?php endif; ?>
<h3>کد کارگاه بیمه</h3><?php if($edit): ?><form method="post" class="erp-form"><?php self::form('module_payroll_workshop',$cid,'payroll_setup'); self::input('workshop','کد کارگاه',Settings::get('insurance_workshop_code',$cid),'text','inputmode="numeric" maxlength="15" dir="ltr"'); ?><button type="submit" class="btn btn-outline">ذخیره</button></form><?php else: ?><p dir="ltr"><?php echo esc_html(Settings::get('insurance_workshop_code',$cid)?:'—'); ?></p><?php endif; ?>
</section>
